// app/dashboard/(inner)/chat/page.tsx
"use client";

import React, { useEffect, useReducer, useRef, useState } from 'react';
import {
    MessageCircle,
    Search,
    Send,
    User,
    ChevronLeft,
    Trash2,
    Check,
    CheckCheck,
    Loader2,
    ShieldCheck,
    Sparkles,
    Users
} from 'lucide-react';
import { db } from '@/lib/firebase';
import {
    collection,
    query,
    orderBy,
    onSnapshot,
    addDoc,
    serverTimestamp,
    doc,
    updateDoc,
    deleteDoc,
    limit
} from 'firebase/firestore';
import { toast } from 'react-hot-toast';
import { format } from 'date-fns';
import { es } from 'date-fns/locale';
import { getSpecialtyById, Specialty } from '@/lib/specialties';
import { motion, AnimatePresence } from 'framer-motion';

interface Message {
    id: string;
    text: string;
    sender: 'visitor' | 'doctor' | 'assistant';
    timestamp: any;
    read: boolean;
}

interface ChatSession {
    id: string;
    visitorName: string;
    lastMessage: string;
    lastMessageTime: any;
    unreadCount: number;
    status: 'active' | 'archived' | 'deleted';
    isRegistered?: boolean;
}

type ChatState = {
    activeChats: ChatSession[];
    currentChat: ChatSession | null;
    messages: Message[];
    searchTerm: string;
    inputText: string;
    loading: boolean;
};

type ChatAction =
    | { type: 'setActiveChats'; payload: ChatSession[] }
    | { type: 'setCurrentChat'; payload: ChatSession | null }
    | { type: 'setMessages'; payload: Message[] }
    | { type: 'setSearchTerm'; payload: string }
    | { type: 'setInputText'; payload: string }
    | { type: 'setLoading'; payload: boolean };

const initialState: ChatState = {
    activeChats: [],
    currentChat: null,
    messages: [],
    searchTerm: '',
    inputText: '',
    loading: true,
};

function chatReducer(state: ChatState, action: ChatAction): ChatState {
    switch (action.type) {
        case 'setActiveChats':
            return { ...state, activeChats: action.payload };
        case 'setCurrentChat':
            return { ...state, currentChat: action.payload };
        case 'setMessages':
            return { ...state, messages: action.payload };
        case 'setSearchTerm':
            return { ...state, searchTerm: action.payload };
        case 'setInputText':
            return { ...state, inputText: action.payload };
        case 'setLoading':
            return { ...state, loading: action.payload };
        default:
            return state;
    }
}

export default function ChatPage() {
    const [state, dispatch] = useReducer(chatReducer, initialState);
    const [specialty, setSpecialty] = useState<Specialty | null>(null);
    const messagesEndRef = useRef<HTMLDivElement>(null);

    // Load Specialty
    useEffect(() => {
        const specId = typeof window !== 'undefined' ? localStorage.getItem('selectedSpecialty') || 'gastroenterology' : 'gastroenterology';
        setSpecialty(getSpecialtyById(specId));
    }, []);

    // Sidebar Listener: List of Chats
    useEffect(() => {
        const q = query(
            collection(db, 'chats'),
            orderBy('lastMessageTime', 'desc')
        );

        const unsubscribe = onSnapshot(q, (snapshot) => {
            const chats = snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() })) as ChatSession[];
            dispatch({ type: 'setActiveChats', payload: chats });
            dispatch({ type: 'setLoading', payload: false });
        });

        return () => unsubscribe();
    }, []);

    // Messages Listener: Current Chat Messages
    useEffect(() => {
        if (!state.currentChat) {
            dispatch({ type: 'setMessages', payload: [] });
            return;
        }

        const q = query(
            collection(db, 'chats', state.currentChat.id, 'messages'),
            orderBy('timestamp', 'asc'),
            limit(50)
        );

        const unsubscribe = onSnapshot(q, (snapshot) => {
            const msgs = snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() })) as Message[];
            dispatch({ type: 'setMessages', payload: msgs });

            // Auto scroll to bottom
            setTimeout(() => {
                messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
            }, 100);
        });

        // Mark as read when opening chat
        const markAsRead = async () => {
            try {
                const chatRef = doc(db, 'chats', state.currentChat!.id);
                await updateDoc(chatRef, { unreadCount: 0 });
            } catch (error) {
                console.error("Error marking as read:", error);
            }
        };
        markAsRead();

        return () => unsubscribe();
    }, [state.currentChat]);

    const handleSend = async (e?: React.FormEvent) => {
        e?.preventDefault();
        if (!state.inputText.trim() || !state.currentChat) return;

        const text = state.inputText;
        dispatch({ type: 'setInputText', payload: '' });

        try {
            await addDoc(collection(db, 'chats', state.currentChat.id, 'messages'), {
                text,
                sender: 'doctor',
                timestamp: serverTimestamp(),
                read: false
            });

            const chatRef = doc(db, 'chats', state.currentChat.id);
            await updateDoc(chatRef, {
                lastMessage: text,
                lastMessageTime: serverTimestamp()
            });
        } catch (error) {
            toast.error("Error al enviar mensaje");
        }
    };

    const handleDeleteChat = async (id: string) => {
        if (!confirm("-+Desea eliminar este chat?")) return;
        try {
            await deleteDoc(doc(db, 'chats', id));
            if (state.currentChat?.id === id) dispatch({ type: 'setCurrentChat', payload: null });
            toast.success("Chat eliminado");
        } catch (error) {
            toast.error("Error al eliminar");
        }
    };

    const filteredChats = state.activeChats.filter(chat =>
        chat.visitorName?.toLowerCase().includes(state.searchTerm.toLowerCase()) ||
        chat.lastMessage?.toLowerCase().includes(state.searchTerm.toLowerCase())
    );

    if (state.loading && state.activeChats.length === 0) return (
        <div className="flex h-screen items-center justify-center bg-background">
            <Loader2 className="w-10 h-10 animate-spin text-primary" />
        </div>
    );

    return (
        <div className="flex h-[calc(100vh-140px)] bg-card/40 backdrop-blur-3xl rounded-[2.5rem] shadow-soft border border-border/40 overflow-hidden relative group">
            {/* Liquid Gold Decor */}
            <div className="absolute top-0 right-0 w-[500px] h-[500px] bg-primary/5 rounded-full blur-[100px] -z-10 group-hover:bg-primary/10 transition-all duration-700" />

            {/* Sidebar Explorer */}
            <div className={`w-full md:w-[400px] border-r border-border/40 flex flex-col bg-muted/20 backdrop-blur-3xl transition-all duration-500 ${state.currentChat ? 'hidden md:flex' : 'flex'}`}>
                <div className="p-8 border-b border-border/40 bg-card/30">
                    <div className="flex items-center justify-between mb-8">
                        <div>
                            <h2 className="text-3xl font-black text-foreground tracking-tighter uppercase">Mensajes</h2>
                            <p className="text-[10px] font-black text-primary/60 uppercase tracking-[0.3em] mt-1 italic">Centro de Comunicaci+¶n</p>
                        </div>
                        <div className="p-3 bg-primary/10 rounded-2xl border border-primary/20">
                            <MessageCircle className="text-primary" size={24} />
                        </div>
                    </div>
                    <div className="relative group/search">
                        <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-muted-foreground group-focus-within/search:text-primary transition-colors" size={18} />
                        <input
                            type="text"
                            placeholder="Buscar conversaciones..."
                            className="w-full pl-12 pr-6 py-4 bg-background/50 border border-border/40 rounded-[1.5rem] text-sm font-bold focus:ring-4 focus:ring-primary/10 focus:border-primary/40 outline-none transition-all shadow-inner"
                            value={state.searchTerm}
                            onChange={(e) => dispatch({ type: 'setSearchTerm', payload: e.target.value })}
                        />
                    </div>
                </div>

                <div className="flex-1 overflow-y-auto custom-scrollbar p-2">
                    <AnimatePresence>
                        {filteredChats.length === 0 ? (
                            <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="p-12 text-center text-muted-foreground/30 flex flex-col items-center">
                                <Users size={64} className="mb-4 opacity-10" />
                                <p className="text-[10px] font-black uppercase tracking-widest">No hay chats activos</p>
                            </motion.div>
                        ) : (
                            filteredChats.map((chat, idx) => (
                                <motion.button
                                    initial={{ opacity: 0, x: -10 }}
                                    animate={{ opacity: 1, x: 0 }}
                                    transition={{ delay: idx * 0.05 }}
                                    key={chat.id}
                                    onClick={() => dispatch({ type: 'setCurrentChat', payload: chat })}
                                    className={`w-full p-6 flex items-start gap-5 hover:bg-card/40 transition-all text-left rounded-[2rem] mb-2 pointer group/chat-btn ${state.currentChat?.id === chat.id ? 'bg-card shadow-lg border border-primary/20 scale-[0.98]' : 'border border-transparent'}`}
                                >
                                    <div className="relative">
                                        <div className="w-14 h-14 rounded-2xl bg-gradient-to-br from-primary/20 to-indigo-500/20 flex items-center justify-center text-primary font-black text-xl border border-primary/20 group-hover/chat-btn:scale-110 transition-transform">
                                            {chat.visitorName?.charAt(0) || 'V'}
                                        </div>
                                        {chat.unreadCount > 0 && (
                                            <span className="absolute -top-2 -right-2 w-7 h-7 bg-primary text-white text-[10px] font-black rounded-full flex items-center justify-center border-4 border-card shadow-lg">
                                                {chat.unreadCount}
                                            </span>
                                        )}
                                    </div>
                                    <div className="flex-1 min-w-0">
                                        <div className="flex justify-between items-start mb-2">
                                            <h3 className="font-black text-foreground tracking-tight truncate uppercase text-sm">{chat.visitorName}</h3>
                                            <span className="text-[9px] font-black text-muted-foreground/40 uppercase tracking-widest">
                                                {chat.lastMessageTime?.toDate ? format(chat.lastMessageTime.toDate(), 'HH:mm') : ''}
                                            </span>
                                        </div>
                                        <p className="text-xs text-muted-foreground line-clamp-1 group-hover/chat-btn:text-foreground/80 transition-colors">{chat.lastMessage}</p>
                                    </div>
                                </motion.button>
                            ))
                        )}
                    </AnimatePresence>
                </div>

                {/* Specialty Banner at bottom of sidebar */}
                {specialty && (
                    <div className="p-6 bg-primary/5 border-t border-primary/10 flex items-center justify-center gap-2">
                        <span className="text-[9px] font-black text-primary uppercase tracking-[0.4em] opacity-60">Filtro: {specialty.nameEs}</span>
                    </div>
                )}
            </div>

            {/* Conversation Area */}
            <div className={`flex-1 flex flex-col bg-background/30 backdrop-blur-3xl ${state.currentChat ? 'flex' : 'hidden md:flex'}`}>
                {state.currentChat ? (
                    <>
                        {/* Header Explorer */}
                        <div className="p-6 border-b border-border/40 flex justify-between items-center bg-card/20">
                            <div className="flex items-center gap-5">
                                <motion.button
                                    whileHover={{ scale: 1.1 }}
                                    whileTap={{ scale: 0.9 }}
                                    onClick={() => dispatch({ type: 'setCurrentChat', payload: null })}
                                    className="md:hidden p-3 text-muted-foreground hover:bg-muted rounded-2xl transition-all"
                                >
                                    <ChevronLeft size={24} />
                                </motion.button>
                                <div className="w-14 h-14 rounded-2xl bg-muted/50 flex items-center justify-center text-primary border border-border/40 shadow-inner">
                                    <User size={28} />
                                </div>
                                <div>
                                    <h2 className="font-black text-2xl text-foreground tracking-tighter uppercase">{state.currentChat.visitorName}</h2>
                                    <div className="flex items-center gap-2 text-[10px] text-emerald-500 font-black uppercase tracking-[0.2em] mt-1">
                                        <span className="w-1.5 h-1.5 bg-emerald-500 rounded-full animate-pulse"></span>
                                        En comunicaci+¶n activa
                                    </div>
                                </div>
                            </div>
                            <button
                                onClick={() => handleDeleteChat(state.currentChat.id)}
                                className="p-4 text-muted-foreground/30 hover:text-destructive hover:bg-destructive/10 rounded-2xl transition-all border border-transparent hover:border-destructive/20"
                            >
                                <Trash2 size={24} />
                            </button>
                        </div>

                        {/* Liquid Message Stream */}
                        <div className="flex-1 overflow-y-auto p-10 space-y-8 custom-scrollbar bg-slate-500/5">
                            <AnimatePresence>
                                {state.messages.map((msg, idx) => {
                                    const isMe = msg.sender === 'doctor';
                                    return (
                                        <motion.div
                                            initial={{ opacity: 0, y: 10, scale: 0.98 }}
                                            animate={{ opacity: 1, y: 0, scale: 1 }}
                                            key={msg.id}
                                            className={`flex ${isMe ? 'justify-end' : 'justify-start'}`}
                                        >
                                            <div className={`max-w-[70%] p-6 rounded-[2.5rem] shadow-xl relative group/msg transition-all hover:shadow-2xl ${isMe ? 'bg-primary text-primary-foreground rounded-tr-none shadow-primary/10' : 'bg-card text-foreground rounded-tl-none border border-border/40'}`}>
                                                <p className="text-sm font-medium leading-relaxed">{msg.text}</p>
                                                <div className={`flex items-center justify-end gap-2 mt-3 text-[9px] font-black uppercase tracking-widest ${isMe ? 'text-primary-foreground/60' : 'text-muted-foreground/40'}`}>
                                                    <span>{msg.timestamp?.toDate ? format(msg.timestamp.toDate(), 'HH:mm') : '...'}</span>
                                                    {isMe && (msg.read ? <CheckCheck size={12} className="text-white" /> : <Check size={12} />)}
                                                </div>
                                            </div>
                                        </motion.div>
                                    );
                                })}
                            </AnimatePresence>
                            <div ref={messagesEndRef} />
                        </div>

                        {/* Neo Input Field */}
                        <div className="p-10 bg-card/40 border-t border-border/40">
                            <form onSubmit={handleSend} className="flex items-center gap-6 bg-background/80 p-3 pl-6 rounded-[2.5rem] border border-border/40 shadow-2xl focus-within:border-primary/40 transition-all group/input">
                                <Sparkles size={20} className="text-primary/20 group-focus-within/input:text-primary transition-colors" />
                                <input
                                    type="text"
                                    value={state.inputText}
                                    onChange={(e) => dispatch({ type: 'setInputText', payload: e.target.value })}
                                    placeholder="Escribe tu respuesta profesional..."
                                    className="flex-1 bg-transparent border-none outline-none text-sm font-bold py-4 placeholder:text-muted-foreground/30 text-foreground"
                                />
                                <motion.button
                                    whileHover={{ scale: 1.05, rotate: 5 }}
                                    whileTap={{ scale: 0.95 }}
                                    type="submit"
                                    disabled={!state.inputText.trim()}
                                    className="p-5 bg-primary text-primary-foreground rounded-[2rem] hover:bg-primary/90 transition-all shadow-xl shadow-primary/20 disabled:opacity-20"
                                >
                                    <Send size={24} />
                                </motion.button>
                            </form>
                            <div className="flex justify-center mt-6">
                                <p className="text-[9px] font-black text-muted-foreground/20 uppercase tracking-[0.5em] italic flex items-center gap-2">
                                    <ShieldCheck size={10} /> Canal de Comunicaci+¶n Cifrado JEE-PRO v4.2
                                </p>
                            </div>
                        </div>
                    </>
                ) : (
                    <div className="flex-1 flex flex-col items-center justify-center text-center p-20">
                        <div className="w-32 h-32 rounded-[3rem] bg-muted/30 flex items-center justify-center mb-10 border-2 border-dashed border-border/60 animate-pulse">
                            <MessageCircle size={64} className="opacity-10 text-primary" />
                        </div>
                        <h3 className="text-3xl font-black text-foreground tracking-tighter uppercase mb-4">Canal Directo JE</h3>
                        <p className="text-muted-foreground/40 font-black text-[10px] uppercase tracking-[0.4em] max-w-sm leading-relaxed">Selecciona una conversaci+¶n del panel lateral para iniciar la comunicaci+¶n cl+°nica.</p>
                    </div>
                )}
            </div>

            <style jsx global>{`
                .custom-scrollbar::-webkit-scrollbar {
                    width: 4px;
                }
                .custom-scrollbar::-webkit-scrollbar-track {
                    background: transparent;
                }
                .custom-scrollbar::-webkit-scrollbar-thumb {
                    background: rgba(var(--primary), 0.1);
                    border-radius: 20px;
                }
            `}</style>
        </div>
    );
}

"use client";

import React, { useState, useEffect } from 'react';
import { useRouter, useParams } from 'next/navigation';
import { useForm, FormProvider } from 'react-hook-form';
import { Save, ArrowLeft, Loader2, Plus, Trash2, Activity } from 'lucide-react';

import { api } from '@/lib/api';
import { Patient, SubsequentConsult } from '@/types';
import * as C from '@/constants';

// UI Components
import { FloatingLabelInput } from '@/components/premium-ui/FloatingLabelInput';
import { CheckboxList, PhysicalExamSection } from '@/components/ui/FormComponents';
import { ObesityHistoryModal } from '@/components/ObesityHistoryModal';
import { toast } from 'react-hot-toast';

import { motion } from 'framer-motion';
import { getSpecialtyById, Specialty } from '@/lib/specialties';

export default function NewConsultClient() {
    const router = useRouter();
    const params = useParams();
    const patientId = params?.id as string;

    const [loading, setLoading] = useState(true);
    const [patient, setPatient] = useState<Patient | null>(null);
    const [showObesityModal, setShowObesityModal] = useState(false);
    const [specialty, setSpecialty] = useState<Specialty | null>(null);

    const methods = useForm<SubsequentConsult>({
        defaultValues: {
            patientId: patientId,
            date: new Date().toISOString().split('T')[0],
            time: new Date().toLocaleTimeString('es-ES', { hour: '2-digit', minute: '2-digit' }),
            motives: {},
            otherMotive: '',
            evolutionTime: '',
            historyOfPresentIllness: '',
            physicalExam: {
                fc: '', fr: '', temp: '', pa: '', pam: '', sat02: '', weight: '', height: '', imc: '',
                systems: C.SYSTEMS_LIST.reduce((acc, sys) => ({ ...acc, [sys]: { normal: true, abnormal: false, description: '' } }), {})
            },
            labs: { performed: { yes: false, no: true }, results: '' },
            comments: '',
            diagnoses: [''],
            treatment: {
                food: '',
                meds: [''],
                exams: [''],
                norms: ['']
            },
            status: 'completed'
        }
    });

    const { handleSubmit, watch, setValue, formState: { isSubmitting } } = methods;

    useEffect(() => {
        const loadPatient = async () => {
            if (!patientId) return;
            try {
                // Detect Specialty
                const specId = typeof window !== 'undefined' ? localStorage.getItem('selectedSpecialty') || 'gastroenterology' : 'gastroenterology';
                const specData = getSpecialtyById(specId);
                setSpecialty(specData);

                const data = await api.getPatient(patientId);
                setPatient(data);
                setValue('patientId', patientId);
            } catch (error) {
                toast.error("Error al cargar paciente");
            } finally {
                setLoading(false);
            }
        };
        loadPatient();
    }, [patientId, setValue]);

    const weight = watch('physicalExam.weight');
    const height = watch('physicalExam.height');
    useEffect(() => {
        const w = parseFloat(weight);
        const h = parseFloat(height);
        if (w > 0 && h > 0) {
            const imc = (w / ((h / 100) ** 2)).toFixed(1);
            setValue('physicalExam.imc', imc);
        }
    }, [weight, height, setValue]);

    const onSubmit = async (data: SubsequentConsult) => {
        try {
            await api.createConsult(data as any);
            toast.success("Consulta guardada");
            router.push(`/dashboard/patients/${patientId}`);
        } catch (error) {
            toast.error("Error al guardar");
        }
    };

    if (loading) return <div className="h-screen flex items-center justify-center bg-background"><Loader2 className="animate-spin text-primary" size={48} /></div>;
    if (!patient) return <div className="h-screen flex items-center justify-center text-foreground font-black uppercase tracking-widest bg-background">Paciente no encontrado</div>;

    const motives = watch('motives');

    return (
        <FormProvider {...methods}>
            <div className="min-h-screen bg-background transition-colors duration-300">
                {/* Modern Fixed Header */}
                <div className="sticky top-0 z-40 bg-card/70 backdrop-blur-3xl border-b border-border px-8 h-24 flex items-center justify-between shadow-soft">
                    <div className="flex items-center gap-6">
                        <motion.button
                            whileHover={{ scale: 1.1 }}
                            whileTap={{ scale: 0.9 }}
                            onClick={() => router.back()}
                            className="p-3 bg-muted hover:bg-muted/80 rounded-2xl transition-all border border-border"
                        >
                            <ArrowLeft size={20} className="text-foreground" />
                        </motion.button>
                        <div>
                            <div className="flex items-center gap-3">
                                <Activity className="text-emerald-500" size={20} />
                                <h1 className="text-2xl font-black text-foreground tracking-tight">Nueva Consulta - {specialty?.nameEs}</h1>
                            </div>
                            <p className="text-xs font-bold text-muted-foreground uppercase mt-0.5 tracking-widest italic">{patient.firstName} {patient.lastName}</p>
                        </div>
                    </div>

                    <motion.button
                        whileHover={{ scale: 1.05 }}
                        whileTap={{ scale: 0.95 }}
                        onClick={handleSubmit(onSubmit)}
                        disabled={isSubmitting}
                        className="bg-primary text-primary-foreground px-8 py-4 rounded-[2rem] font-black text-xs uppercase tracking-widest flex items-center gap-3 shadow-lg shadow-primary/20 hover:bg-primary/90 transition-all border border-primary/20"
                    >
                        {isSubmitting ? <Loader2 className="animate-spin" size={18} /> : <Save size={18} />}
                        Finalizar Consulta
                    </motion.button>
                </div>

                <div className="max-w-5xl mx-auto p-8 md:p-12 space-y-12 pb-40 relative z-10">
                    {/* Background Glow */}
                    <div className="absolute top-0 right-0 w-[500px] h-[500px] bg-emerald-500/5 rounded-full blur-[120px] -z-10" />

                    {/* Basic Info Card */}
                    <div className="bg-card/60 backdrop-blur-3xl p-10 rounded-[3rem] shadow-soft border border-border/50 grid grid-cols-1 md:grid-cols-2 gap-8 hover:border-border transition-all">
                        <div className="space-y-4">
                            <label className="text-[10px] font-black text-muted-foreground uppercase tracking-[0.2em] ml-4 flex items-center gap-2">
                                <span className="w-1.5 h-1.5 bg-primary rounded-full"></span> Fecha Programada
                            </label>
                            <input type="date" {...methods.register('date')} className="w-full p-5 bg-background border border-border/40 rounded-[1.5rem] focus:border-primary focus:ring-2 focus:ring-primary/20 outline-none transition-all font-bold text-foreground shadow-inner" />
                        </div>
                        <div className="space-y-4">
                            <label className="text-[10px] font-black text-muted-foreground uppercase tracking-[0.2em] ml-4 flex items-center gap-2">
                                <span className="w-1.5 h-1.5 bg-indigo-500 rounded-full"></span> Hora de Inicio
                            </label>
                            <input type="time" {...methods.register('time')} className="w-full p-5 bg-background border border-border/40 rounded-[1.5rem] focus:border-indigo-500 focus:ring-2 focus:ring-indigo-500/20 outline-none transition-all font-bold text-foreground shadow-inner" />
                        </div>
                    </div>

                    {/* Motives Section */}
                    <motion.section
                        initial={{ opacity: 0, y: 20 }}
                        whileInView={{ opacity: 1, y: 0 }}
                        viewport={{ once: true }}
                        className="bg-card/60 backdrop-blur-3xl p-10 rounded-[3rem] shadow-soft border border-border/50 group hover:border-border transition-all"
                    >
                        <div className="flex items-center gap-4 mb-8">
                            <div className="p-4 bg-indigo-500/10 rounded-[1.5rem] border border-indigo-500/20 shadow-inner group-hover:scale-105 transition-transform">
                                <Plus className="text-indigo-500" size={24} />
                            </div>
                            <h3 className="text-xl font-black text-foreground uppercase tracking-[0.2em]">Motivo de Consulta</h3>
                        </div>

                        <div className="bg-background/50 p-6 rounded-[2.5rem] border border-border/40">
                            <CheckboxList
                                items={C.MOTIVES_LIST}
                                data={motives}
                                onChange={(key, val) => {
                                    setValue(`motives.${key}`, val);
                                    if (key === 'Obesidad' && val) setShowObesityModal(true);
                                }}
                            />
                        </div>

                        <div className="mt-10 space-y-8">
                            <FloatingLabelInput label="Especificaciones / Otros Motivos" {...methods.register('otherMotive')} wrapperClassName="border-none bg-background/50 shadow-none hover:bg-background/80" />
                            <FloatingLabelInput label="Tiempo de Evoluci+¶n de los S+°ntomas" {...methods.register('evolutionTime')} wrapperClassName="border-none bg-background/50 shadow-none hover:bg-background/80" />
                        </div>
                    </motion.section>

                    {/* Physical Exam - Using its own modernized component */}
                    <div className="space-y-6">
                        <div className="flex items-center gap-4 px-4">
                            <div className="p-3 bg-emerald-500/10 rounded-2xl border border-emerald-500/20">
                                <Activity className="text-emerald-500" size={24} />
                            </div>
                            <h3 className="text-2xl font-black text-foreground tracking-tight">Constantes Vitales</h3>
                        </div>
                        <PhysicalExamSection
                            data={watch('physicalExam')}
                            onChange={(d) => setValue('physicalExam', d)}
                        />
                    </div>

                    {/* History of Illness */}
                    <motion.section
                        initial={{ opacity: 0, y: 20 }}
                        whileInView={{ opacity: 1, y: 0 }}
                        viewport={{ once: true }}
                        className="bg-card/60 backdrop-blur-3xl p-10 rounded-[3rem] shadow-soft border border-border/50 group hover:border-border transition-all"
                    >
                        <h3 className="text-xl font-black text-foreground mb-8 uppercase tracking-[0.2em] flex items-center gap-4">
                            <span className="w-8 h-1 bg-primary rounded-full"></span>
                            Historia de la Enfermedad
                        </h3>
                        <FloatingLabelInput label="Descripci+¶n detallada de la evoluci+¶n cl+°nica..." as="textarea" rows={6} {...methods.register('historyOfPresentIllness')} wrapperClassName="border-none bg-background/50 shadow-none hover:bg-background/80" />
                    </motion.section>

                    {/* Diagnosis */}
                    <motion.section
                        initial={{ opacity: 0, y: 20 }}
                        whileInView={{ opacity: 1, y: 0 }}
                        viewport={{ once: true }}
                        className="bg-card/60 backdrop-blur-3xl p-10 rounded-[3rem] shadow-soft border border-border/50 group hover:border-border transition-all"
                    >
                        <h3 className="text-xl font-black text-foreground mb-8 uppercase tracking-[0.2em] flex items-center gap-4">
                            <span className="w-8 h-1 bg-emerald-500 rounded-full"></span>
                            Diagn+¶sticos Cl+°nicos
                        </h3>
                        <div className="space-y-4">
                            {watch('diagnoses').map((_, i) => (
                                <div key={i} className="flex gap-4 group/input">
                                    <div className="flex-1 relative">
                                        <input
                                            className="w-full p-5 bg-background border border-border/40 rounded-[1.5rem] focus:border-emerald-500 focus:ring-2 focus:ring-emerald-500/20 outline-none transition-all font-bold text-foreground shadow-inner"
                                            placeholder={`Diagn+¶stico principal o diferencial ${i + 1}...`}
                                            {...methods.register(`diagnoses.${i}`)}
                                        />
