// medical-ai-demo/components/profile/PatientInfoCard.tsx
"use client";

import React, { useRef, useState, useEffect } from 'react';
import { Camera, Edit, User, Phone, Mail, MapPin, Calendar, Activity, Hash, Briefcase, ShieldCheck } from 'lucide-react';
import { Patient } from '@/types';
import { motion } from 'framer-motion';
import Image from 'next/image';
import { getSpecialtyById, Specialty } from '@/lib/specialties';
import { cn } from '@/lib/utils';

interface PatientInfoCardProps {
    patient: Patient;
    onUpdateImage: (file: File) => void;
    onEdit?: () => void;
    uploadingImage?: boolean;
}

export const PatientInfoCard: React.FC<PatientInfoCardProps> = ({ patient, onUpdateImage, onEdit, uploadingImage }) => {
    const fileInputRef = useRef<HTMLInputElement>(null);
    const [specialty, setSpecialty] = useState<Specialty | null>(null);

    useEffect(() => {
        const specId = typeof window !== 'undefined' ? localStorage.getItem('selectedSpecialty') || 'gastroenterology' : 'gastroenterology';
        setSpecialty(getSpecialtyById(specId));
    }, []);

    const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        if (e.target.files && e.target.files[0]) {
            onUpdateImage(e.target.files[0]);
        }
    };

    const isMigrated = patient.legacyIdSistema;
    const formattedBirthDate = typeof patient.birthDate === 'object' && patient.birthDate !== null
        ? new Date((patient.birthDate as any).seconds * 1000).toLocaleDateString()
        : String(patient.birthDate);

    return (
        <motion.div
            initial={{ opacity: 0, x: -15 }}
            animate={{ opacity: 1, x: 0 }}
            className="bg-[#0a0a0a]/60 backdrop-blur-xl rounded-[2rem] p-10 border border-white/5 relative flex flex-col group/card transition-all duration-1000 hover:border-primary/20"
        >
            <div className="flex justify-between items-center mb-10">
                <div className="flex flex-col gap-1">
                    <span className="text-[7px] tracking-[0.6em] text-primary/60 uppercase font-light">
                        FICHA M+ÎDICA
                    </span>
                    <div className="w-6 h-[1px] bg-primary/20" />
                </div>
                {onEdit && (
                    <button
                        onClick={onEdit}
                        className="p-2.5 text-white/20 hover:text-primary transition-all rounded-full border border-white/5 hover:border-primary/20"
                    >
                        <Edit size={12} strokeWidth={1} />
                    </button>
                )}
            </div>

            <div className="flex flex-col items-center mb-14 relative group/avatar">
                <div className="relative">
                    <div className="w-36 h-36 rounded-2xl overflow-hidden bg-white/5 border border-white/5 mb-6 group-hover/avatar:border-primary/40 transition-all duration-1000 relative">
                        {patient.profileImage ? (
                            <Image src={patient.profileImage} alt="Avatar" width={144} height={144} className="w-full h-full object-cover grayscale group-hover/avatar:grayscale-0 transition-all duration-1000" />
                        ) : (
                            <div className="w-full h-full flex items-center justify-center">
                                <User size={40} strokeWidth={1} className="text-white/10" />
                            </div>
                        )}
                        <button type="button" className="absolute inset-0 bg-black/60 opacity-0 group-hover/avatar:opacity-100 transition-opacity flex items-center justify-center cursor-pointer" onClick={() => fileInputRef.current?.click()}>
                            <Camera className="text-white/60" size={20} strokeWidth={1} />
                        </button>
                    </div>
                </div>

                <div className="text-center space-y-1.5">
                    <h2 className="text-2xl font-thin text-white tracking-[0.1em] uppercase leading-tight line-clamp-1">
                        {patient.firstName}
                    </h2>
                    <p className="text-[9px] tracking-[0.4em] text-white/20 uppercase font-light">
                        {patient.lastName}
                    </p>
                </div>

                <input
                    type="file"
                    ref={fileInputRef}
                    onChange={handleFileChange}
                    className="hidden"
                    accept="image/*"
                />
            </div>

            {isMigrated && (
                <div className="bg-primary/5 rounded-2xl p-4 border border-primary/10 mb-10 text-center">
                    <p className="text-[7px] tracking-[0.3em] text-primary uppercase font-bold">LEGACY VALIDATED</p>
                    <p className="text-[6px] tracking-[0.2em] text-primary/40 uppercase mt-0.5">ID: {patient.legacyIdSistema || patient.id.slice(0, 8)}</p>
                </div>
            )}

            <div className="flex flex-col space-y-8 flex-1">
                {[
                    { icon: Briefcase, label: "PROFESI+ÙN", value: patient.profession },
                    { icon: Phone, label: "TEL+ÎFONO", value: patient.phone },
                    { icon: Mail, label: "EMAIL", value: patient.email },
                    { icon: Calendar, label: "NACIMIENTO", value: formattedBirthDate },
                    { icon: MapPin, label: "MODO", value: patient.address, isLong: true }
                ].map((item, idx) => (
                    <div key={idx} className="flex flex-col gap-1.5 px-1 group/item">
                        <div className="flex items-center gap-3">
                            <item.icon size={12} strokeWidth={1} className="text-primary/20 group-hover/item:text-primary transition-colors" />
                            <span className="text-[7px] font-thin uppercase text-white/20 tracking-[0.4em]">{item.label}</span>
                        </div>
                        <span className={cn(
                            "text-[10px] font-light text-white/40 tracking-[0.1em] uppercase pt-0.5 border-white/5 transition-all group-hover:text-white/80",
                            item.isLong ? 'leading-relaxed' : 'line-clamp-1'
                        )}>
                            {item.value || 'N/A'}
                        </span>
                    </div>
                ))}
            </div>

            {specialty && (
                <div className="mt-12 pt-6 border-t border-white/5 flex items-center justify-center gap-4 opacity-50">
                    <div className="w-0.5 h-0.5 bg-primary/20 rounded-full" />
                    <p className="text-[6px] tracking-[0.6em] text-white/20 uppercase font-light">
                        {specialty.nameEs}
                    </p>
                </div>
            )}
        </motion.div>
    );
};

import React from 'react';
import { cn } from '@/lib/utils';

export const ActionButton = ({ icon, label, onClick, color = 'blue', active = false, variant = 'default' }: any) => {
    const colors: any = {
        blue: 'hover:bg_blue-500/10 text-blue-600 dark:text-blue-400',
        indigo: 'hover:bg-indigo-500/10 text-indigo-600 dark:text-indigo-400',
        amber: 'hover:bg-amber-500/10 text-amber-600 dark:text-amber-400',
        teal: 'hover:bg-teal-500/10 text-teal-600 dark:text-teal-400',
        red: 'hover:bg-red-500/10 text-red-600 dark:text-red-400',
        gray: 'hover:bg-muted text-foreground'
    };

    if (variant === 'ghost') {
        return (
            <button
                onClick={onClick}
                className={cn(
                    "p-3 rounded-2xl transition-all hover:bg-muted/50 text-muted-foreground hover:text-foreground",
                    colors[color]
                )}
            >
                {icon}
            </button>
        );
    }

    return (
        <button
            onClick={onClick}
            className={cn(
                "flex items-center gap-3 px-6 py-3.5 rounded-[1.5rem] transition-all font-black text-[10px] uppercase tracking-widest",
                active ? 'bg-primary text-primary-foreground shadow-xl shadow-primary/20 scale-105' : cn('text-muted-foreground bg-muted/30 hover:bg-muted/60', colors[color])
            )}
        >
            <div className={cn("shrink-0 transition-transform", active ? 'scale-110' : 'group-hover/btn:scale-110')}>{icon}</div>
            <span className="hidden xl:inline">{label}</span>
        </button>
    );
};

export const ActionButtonSmall = ({ icon, onClick, color }: any) => {
    const colors: any = {
        blue: 'hover:bg-blue-500/10 text-blue-500',
        amber: 'hover:bg-amber-500/10 text-amber-500',
        red: 'hover:bg-destructive/10 text-destructive',
        emerald: 'hover:bg-emerald-500/10 text-emerald-500',
    };
    return (
        <button onClick={(e) => { e.stopPropagation(); onClick(); }} className={cn("p-2.5 rounded-xl transition-all active:scale-90 border border-transparent hover:border-border/50 bg-muted/20", colors[color])}>
            {icon}
        </button>
    );
};

export const InfoItem = ({ icon, label, value }: any) => (
    <div className="flex items-center gap-5 p-5 rounded-[1.8rem] bg-muted/30 border border-border/40 hover:bg-muted/50 hover:border-primary/30 transition-all duration-300 group shadow-sm hover:shadow-md">
        <div className="p-3 rounded-2xl bg-background border border-border/50 text-muted-foreground group-hover:text-primary transition-all group-hover:scale-110 shadow-inner">
            {icon}
        </div>
        <div className="overflow-hidden">
            <p className="text-[9px] font-black text-muted-foreground/60 uppercase tracking-[0.25em] mb-1">{label}</p>
            <p className="text-sm font-black text-foreground truncate tracking-tight">{value || 'N/A'}</p>
        </div>
    </div>
);

import React from 'react';
import { clsx, type ClassValue } from 'clsx';
import { twMerge } from 'tailwind-merge';
import { motion, AnimatePresence } from 'framer-motion';
import { Check, Activity, Wind, Thermometer, HeartPulse, Droplets, Scale, Ruler, Brain } from 'lucide-react';
import { CheckboxData, PhysicalExam } from '@/types';
import * as C from '@/constants';

function cn(...inputs: ClassValue[]) {
    return twMerge(clsx(inputs));
}

const SECTION_TITLE_CLASS = "text-3xl font-black text-foreground mb-10 flex items-center gap-4 tracking-tighter";

// 1. Checkbox List
interface CheckboxListProps {
    items: string[];
    data: CheckboxData;
    onChange: (key: string, value: boolean) => void;
    columns?: number;
}

export const CheckboxList: React.FC<CheckboxListProps> = ({ items, data, onChange, columns = 4 }) => {
    return (
        <div className={cn("grid grid-cols-1 min-[450px]:grid-cols-2 lg:grid-cols-4 gap-4")}>
            {items.map((item) => {
                const isChecked = !!data[item];
                return (
                    <label
                        key={item}
                        className={cn(
                            "flex items-center space-x-4 p-5 rounded-[1.5rem] border transition-all cursor-pointer group relative overflow-hidden",
                            isChecked
                                ? "bg-primary/10 border-primary shadow-[0_0_20px_rgba(198,147,32,0.1)] scale-[1.02]"
                                : "bg-black/40 border-white/5 hover:border-white/10 hover:bg-black/60 shadow-inner"
                        )}
                    >
                        <div className="relative flex items-center justify-center shrink-0">
                            <input
                                type="checkbox"
                                className="peer h-5 w-5 rounded-full border border-white/10 bg-black/40 checked:bg-primary checked:border-primary transition-all cursor-pointer appearance-none"
                                checked={isChecked}
                                onChange={(e) => onChange(item, e.target.checked)}
                            />
                            <Check
                                size={12}
                                className={cn(
                                    "absolute opacity-0 peer-checked:opacity-100 transition-opacity pointer-events-none stroke-[4]",
                                    isChecked ? "text-black" : "text-white"
                                )}
                            />
                        </div>
                        <span className={cn(
                            "text-[9px] font-bold uppercase tracking-[0.2em] transition-colors",
                            isChecked ? "text-primary" : "text-white/40 group-hover:text-white"
                        )}>
                            {item}
                        </span>
                    </label>
                );
            })}
        </div>
    );
};

export const ToggleButton = ({ label, checked, onClick, color = 'gold' }: { label: string, checked: boolean, onClick: () => void, color?: string }) => {
    const activeColors: any = {
        gold: "bg-primary text-black border-primary shadow-xl shadow-primary/20 scale-105",
        emerald: "bg-emerald-500/20 text-emerald-400 border-emerald-500/40 shadow-xl shadow-emerald-500/10 scale-105",
        rose: "bg-rose-500/20 text-rose-400 border-rose-500/40 shadow-xl shadow-rose-500/10 scale-105",
        amber: "bg-amber-500/20 text-amber-400 border-amber-500/40 shadow-xl shadow-amber-500/10 scale-105",
    };

    return (
        <button
            type="button"
            onClick={onClick}
            className={cn(
                "px-8 py-3.5 rounded-[1.5rem] text-[10px] font-black uppercase tracking-[0.3em] transition-all border active:scale-95",
                checked
                    ? (activeColors[color] || activeColors.gold)
                    : "bg-black/40 text-white/20 border-white/5 hover:bg-black/60 hover:text-white shadow-inner"
            )}
        >
            {label}
        </button>
    );
};

// 3. Yes/No Component
interface YesNoProps {
    label: string,
    value?: { yes: boolean, no: boolean, na?: boolean },
    onChange: (key: string, val: boolean) => void,
    allowNa?: boolean
    className?: string;
}

export const YesNo: React.FC<YesNoProps> = ({
    label, value = { yes: false, no: false }, onChange
}) => (
    <div className="flex flex-col md:flex-row md:items-center justify-between p-10 rounded-[3rem] bg-black/40 border border-white/5 transition-all duration-700 hover:border-white/10 gap-8 group">
        <div className="flex items-center gap-6">
            <div className="w-1.5 h-1.5 rounded-full bg-primary animate-pulse opacity-40 group-hover:opacity-100" />
            <span className="font-bold text-white/40 text-[10px] uppercase tracking-[0.4em] group-hover:text-white transition-colors">{label}</span>
        </div>
        <div className="flex gap-4">
            <ToggleButton label="SI" checked={value.yes} onClick={() => onChange('yes', true)} color="emerald" />
            <ToggleButton label="NO" checked={value.no} onClick={() => onChange('no', true)} color="rose" />
        </div>
    </div>
);

// 4. Physical Exam Section
interface PhysicalExamSectionProps {
    data: PhysicalExam;
    onChange: (d: PhysicalExam) => void;
    hideVitals?: boolean;
    title?: string;
}

export const PhysicalExamSection = ({
    data, onChange, hideVitals = false, title
}: PhysicalExamSectionProps) => {
    const systems = data.systems || {};

    const updateSystem = (sys: string, field: 'normal' | 'abnormal' | 'description', val: any) => {
        const currentSystem = systems[sys] || { normal: true, abnormal: false, description: '' };
        let newData = { ...currentSystem, [field]: val };
        if (field === 'normal' && val === true) newData.abnormal = false;
        else if (field === 'abnormal' && val === true) newData.normal = false;

        onChange({
            ...data,
            systems: { ...systems, [sys]: newData }
        });
    };

    return (
        <div className="bg-[#0a0a0a]/40 backdrop-blur-xl p-10 rounded-[3.5rem] border border-white/5 transition-all duration-700 hover:border-primary/20 relative overflow-hidden">
            <div className="flex items-center gap-4 mb-10">
                <div className="w-8 h-8 rounded-full bg-primary/10 flex items-center justify-center">
                    <div className="w-1.5 h-1.5 rounded-full bg-primary animate-pulse" />
                </div>
                <h3 className="text-[11px] tracking-[0.5em] font-light text-white uppercase italic">{title || "Revisi+¶n por Sistemas"}</h3>
            </div>

            <div className="space-y-4">
                {C.SYSTEMS_LIST.map((sys, idx) => {
                    const sysData = systems[sys] || { normal: true, abnormal: false, description: '' };
                    return (
                        <motion.div
                            key={sys}
                            initial={{ opacity: 0, x: 10 }}
                            animate={{ opacity: 1, x: 0 }}
                            transition={{ delay: idx * 0.05 }}
                            className="p-6 rounded-[2rem] bg-black/20 border border-white/5 hover:border-white/10 transition-all group"
                        >
                            <div className="flex items-center justify-between mb-4">
                                <span className={cn(
                                    "text-[9px] font-bold uppercase tracking-[0.2em] transition-colors",
                                    sysData.abnormal ? "text-rose-400" : "text-white/40 group-hover:text-white"
                                )}>
                                    {sys}
                                </span>

                                <div className="flex gap-2">
                                    <button
                                        onClick={() => updateSystem(sys, 'normal', true)}
                                        className={cn(
                                            "px-4 py-1.5 rounded-full text-[8px] uppercase tracking-widest font-bold border transition-all",
                                            sysData.normal
                                                ? "bg-emerald-500/10 border-emerald-500/40 text-emerald-400"
                                                : "bg-black/40 border-white/5 text-white/20 hover:border-white/20"
                                        )}
                                    >
                                        Norm
                                    </button>
                                    <button
                                        onClick={() => updateSystem(sys, 'abnormal', true)}
                                        className={cn(
                                            "px-4 py-1.5 rounded-full text-[8px] uppercase tracking-widest font-bold border transition-all",
                                            sysData.abnormal
                                                ? "bg-rose-500/10 border-rose-500/40 text-rose-400 shadow-[0_0_10px_rgba(244,63,94,0.2)]"
                                                : "bg-black/40 border-white/5 text-white/20 hover:border-white/20"
                                        )}
                                    >
                                        Hall
                                    </button>
                                </div>
                            </div>

                            <textarea
                                className={cn(
                                    "w-full bg-black/40 border border-white/5 rounded-xl p-4 text-[10px] text-white/80 outline-none focus:border-primary/40 focus:bg-black/60 transition-all resize-none tracking-widest placeholder:text-white/5 min-h-[60px]",
                                    sysData.abnormal ? "border-rose-500/20 text-rose-200" : "font-light"
                                )}
                                placeholder={`Notas...`}
                                value={sysData.description || ''}
                                onChange={e => updateSystem(sys, 'description', e.target.value)}
                            />
                        </motion.div>
                    );
                })}
            </div>

            {/* Soft decorative background glow */}
            <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-full h-full bg-primary/[0.01] rounded-full blur-[200px] pointer-events-none" />
        </div>
    );
};

"use client";
import { cn } from "@/lib/utils";
import Link from "next/link";
import React, { useState, createContext, useContext } from "react";
import { AnimatePresence, motion } from "framer-motion";
import { Menu, X } from "lucide-react";

interface Links {
    label: string;
    href: string;
    icon: React.JSX.Element | React.ReactNode;
}

interface SidebarContextProps {
    open: boolean;
    setOpen: React.Dispatch<React.SetStateAction<boolean>>;
    animate: boolean;
}

const SidebarContext = createContext<SidebarContextProps | undefined>(undefined);

export const useSidebar = () => {
    const context = useContext(SidebarContext);
    if (!context) {
        throw new Error("useSidebar must be used within a SidebarProvider");
    }
    return context;
};

export const SidebarProvider = ({
    children,
    open: openProp,
    setOpen: setOpenProp,
    animate = true,
}: {
    children: React.ReactNode;
    open?: boolean;
    setOpen?: React.Dispatch<React.SetStateAction<boolean>>;
    animate?: boolean;
}) => {
    const [openState, setOpenState] = useState(false);

    const open = openProp !== undefined ? openProp : openState;
    const setOpen = setOpenProp !== undefined ? setOpenProp : setOpenState;

    return (
        <SidebarContext.Provider value={{ open, setOpen, animate }}>
            {children}
        </SidebarContext.Provider>
    );
};

export const Sidebar = ({
    children,
    open,
    setOpen,
    animate,
}: {
    children: React.ReactNode;
    open?: boolean;
    setOpen?: React.Dispatch<React.SetStateAction<boolean>>;
    animate?: boolean;
}) => {
    return (
        <SidebarProvider open={open} setOpen={setOpen} animate={animate}>
            {children}
        </SidebarProvider>
    );
};

export const SidebarBody = (props: React.ComponentProps<typeof motion.div>) => {
    return (
        <>
            <DesktopSidebar {...props} />
            <MobileSidebar {...(props as any)} />
        </>
    );
};

export const DesktopSidebar = ({
    className,
    children,
    ...props
}: React.ComponentProps<typeof motion.div>) => {
    const { open, setOpen, animate } = useSidebar();
    return (
        <>
            <motion.div
                className={cn(
                    "h-full px-4 py-4 hidden md:flex md:flex-col bg-white w-[300px] flex-shrink-0 border-r border-gray-200 shadow-xl shadow-blue-900/5",
                    className
                )}
                animate={{
                    width: animate ? (open ? "300px" : "80px") : "300px",
                }}
                onMouseEnter={() => setOpen(true)}
                onMouseLeave={() => setOpen(false)}
                {...props}
            >
                {children}
            </motion.div>
        </>
    );
};

export const MobileSidebar = ({
    className,
    children,
    ...props
}: React.ComponentProps<typeof motion.div>) => {
    const { open, setOpen } = useSidebar();
    return (
        <>
            <div
                className={cn(
                    "h-16 px-4 py-4 flex flex-row md:hidden items-center justify-between bg-white border-b border-gray-100 w-full shadow-sm"
                )}
                {...(props as any)}
            >
                <div className="flex justify-end z-20 w-full">
                    <Menu
                        className="text-gray-700 cursor-pointer"
                        onClick={() => setOpen(!open)}
                    />
                </div>
                <AnimatePresence>
                    {open && (
                        <motion.div
                            initial={{ x: "-100%", opacity: 0 }}
                            animate={{ x: 0, opacity: 1 }}
                            exit={{ x: "-100%", opacity: 0 }}
                            transition={{
                                duration: 0.3,
                                ease: "easeInOut",
                            }}
                            className={cn(
                                "fixed h-full w-full inset-0 bg-white p-10 z-[100] flex flex-col justify-between shadow-2xl",
                                className
                            )}
                        >
                            <div
                                className="absolute right-10 top-10 z-50 text-gray-700 cursor-pointer"
                                onClick={() => setOpen(!open)}
                            >
                                <X />
                            </div>
                            {children as React.ReactNode}
                        </motion.div>
                    )}
                </AnimatePresence>
            </div>
        </>
    );
};

export const SidebarLink = ({
    link,
    className,
    isActive,
    ...props
}: {
    link: Links;
    className?: string;
    isActive?: boolean;
} & Omit<React.ComponentProps<typeof Link>, "href">) => {
    const { open, animate } = useSidebar();
    return (
        <Link
            {...props}
            href={link.href}
            className={cn(
                "flex items-center justify-start gap-2 group/sidebar py-2 cursor-pointer hover:bg-blue-50 rounded-lg px-2 transition-colors no-underline",
                isActive && "bg-[#083c79]/10",
                className
            )}
        >
            {isActive ? (
                React.isValidElement(link.icon) ? (
                    React.cloneElement(link.icon as React.ReactElement<{ className?: string }>, {
                        className: cn((link.icon.props as { className?: string }).className, "!text-[#083c79]")
                    })
                ) : (
                    link.icon
                )
            ) : (
                link.icon
            )}

            <motion.span
                animate={{
                    display: animate ? (open ? "inline-block" : "none") : "inline-block",
                    opacity: animate ? (open ? 1 : 0) : 1,
                }}
                className={cn(
                    "font-bold text-sm group-hover/sidebar:text-blue-600 transition duration-150 whitespace-pre inline-block !p-0 !m-0",
                    isActive ? "text-[#083c79] font-bold" : "text-black"
                )}
            >
                {link.label}
            </motion.span>
        </Link>
    );
};

import React, { useState, useEffect } from 'react';
import { X, Calendar as CalendarIcon, Clock, CheckCircle, AlertCircle, Lightbulb } from 'lucide-react';
import { GlassCard } from './premium-ui/GlassCard';
import { FloatingLabelInput } from './premium-ui/FloatingLabelInput';
import { api } from '../lib/api';
import { Patient } from '../types';

// Available time slots for appointments (60 min intervals)
const TIME_SLOTS = [
    '08:00', '09:00', '10:00', '11:00', '12:00',
    '13:00', '14:00', '15:00', '16:00', '17:00', '18:00'
];

// Appointment duration in minutes
const APPOINTMENT_DURATION = 60;

interface AppointmentModalProps {
    isOpen: boolean;
    onClose: () => void;
    onSuccess: () => void;
    patients: Patient[];
    preSelectedPatientId?: string;
}

export const AppointmentModal = ({ isOpen, onClose, onSuccess, patients, preSelectedPatientId }: AppointmentModalProps) => {
    const [loading, setLoading] = useState(false);
    const [checking, setChecking] = useState(false);
    const [availabilityMsg, setAvailabilityMsg] = useState<{ type: 'success' | 'error' | 'neutral', text: string } | null>(null);
    const [suggestion, setSuggestion] = useState<{ date: string; label: string } | null>(null);

    const [formData, setFormData] = useState<{
        patientId: string;
        date: string;
        time: string;
        type: 'presencial' | 'virtual';
        reason: string;
    }>({
        patientId: preSelectedPatientId || '',
        date: new Date().toISOString().split('T')[0],
        time: '09:00',
        type: 'presencial',
        reason: ''
    });

    const getSuggestedFollowUp = (text: string) => {
        if (!text || text.length < 3) return null;
        const lower = text.toLowerCase();
        const today = new Date();

        if (lower.match(/diabetes|hta|cr+¶nico|cronico/)) {
            const d = new Date(today);
            d.setMonth(d.getMonth() + 3);
            return { date: d.toISOString().split('T')[0], label: '3 meses' };
        }
        if (lower.match(/infecci+¶n|infeccion|agudo|gripe/)) {
            const d = new Date(today);
            d.setDate(d.getDate() + 7);
            return { date: d.toISOString().split('T')[0], label: '7 d+°as' };
        }
        if (lower.match(/control|ni+¶o sano/)) {
            const d = new Date(today);
            d.setFullYear(d.getFullYear() + 1);
            return { date: d.toISOString().split('T')[0], label: '1 a+¶o' };
        }

        // Default logic: If there is text but no specific match, suggest 1 month
        const d = new Date(today);
        d.setMonth(d.getMonth() + 1);
        return { date: d.toISOString().split('T')[0], label: '1 mes' };
    };

    useEffect(() => {
        const sugg = getSuggestedFollowUp(formData.reason);
        setSuggestion(sugg);
    }, [formData.reason]);

    useEffect(() => {
        if (preSelectedPatientId) {
            setFormData(prev => ({ ...prev, patientId: preSelectedPatientId }));
        }
    }, [preSelectedPatientId]);

    // Check availability when date or time changes
    useEffect(() => {
        const checkAvailability = async () => {
            if (!formData.date || !formData.time) return;

            setChecking(true);
            setAvailabilityMsg(null);

            try {
                // Fetch all appointments to check for conflicts
                const appointments = await api.getAppointments();

                // Check for 60-minute window overlap
                const requestedTime = new Date(`${formData.date}T${formData.time}:00`);
                const requestedEnd = new Date(requestedTime.getTime() + APPOINTMENT_DURATION * 60000);

                const conflict = appointments.find((apt: any) => {
                    if (apt.date !== formData.date) return false;

                    const existingStart = new Date(`${apt.date}T${apt.time}:00`);
                    const existingEnd = new Date(existingStart.getTime() + APPOINTMENT_DURATION * 60000);

                    // Check if times overlap (within 60-minute window)
                    return (requestedTime < existingEnd && requestedEnd > existingStart);
                });

                if (conflict) {
                    setAvailabilityMsg({ type: 'error', text: 'Horario no disponible. El doctor tiene una cita en esta hora (60 min por consulta).' });
                } else {
                    setAvailabilityMsg({ type: 'success', text: 'Horario disponible.' });
                }
            } catch (error) {
                console.error("Error checking availability", error);
            } finally {
                setChecking(false);
            }
        };

        const timeoutId = setTimeout(checkAvailability, 500); // Debounce
        return () => clearTimeout(timeoutId);
    }, [formData.date, formData.time]);

    const handleSubmit = async () => {
        if (!formData.patientId) return alert('Seleccione un paciente');
        if (availabilityMsg?.type === 'error') return alert('El horario seleccionado no est+Ì disponible');

        setLoading(true);
        try {
            await api.createAppointment(formData);
            onSuccess();
            onClose();
        } catch (e) {
            alert('Error al crear cita');
        } finally {
            setLoading(false);
        }
    };

    if (!isOpen) return null;

    return (
        <div className="fixed inset-0 bg-black/50 backdrop-blur-sm z-50 flex items-center justify-center p-4 animate-fade-in">
            <GlassCard className="w-full max-w-md bg-white relative">
                <div className="flex justify-between items-center mb-6">
                    <h3 className="text-xl font-bold text-gray-900 flex items-center gap-2">
                        <CalendarIcon className="text-blue-600" /> Agendar Cita
                    </h3>
                    <button onClick={onClose} className="text-gray-400 hover:text-gray-600 transition-colors">
                        <X size={24} />
                    </button>
                </div>

                <div className="space-y-4">
                    <div>
                        <label className="block text-sm font-bold text-gray-700 mb-1 ml-1">Paciente</label>
                        <select
                            className="w-full px-4 py-3 bg-gray-50 border-2 border-gray-100 rounded-xl focus:border-blue-500 focus:ring-4 focus:ring-blue-500/10 outline-none transition-all font-medium text-gray-700"
                            value={formData.patientId}
                            onChange={e => setFormData({ ...formData, patientId: e.target.value })}
                            disabled={!!preSelectedPatientId}
                        >
                            <option value="">Seleccione un paciente...</option>
                            {patients.map(p => (
                                <option key={p.id} value={p.id}>
                                    {p.firstName} {p.lastName}
                                </option>
                            ))}
                        </select>
                    </div>

                    <div>
                        <label className="block text-sm font-bold text-gray-700 mb-1 ml-1">Tipo de Cita</label>
                        <div className="grid grid-cols-2 gap-3">
                            <button
                                type="button"
                                onClick={() => setFormData({ ...formData, type: 'presencial' })}
                                className={`p-3 rounded-xl border-2 font-bold text-sm transition-all ${formData.type === 'presencial' ? 'border-blue-500 bg-blue-50 text-blue-700' : 'border-gray-100 text-gray-500 hover:border-gray-200'}`}
                            >
                                Presencial
                            </button>
                            <button
                                type="button"
                                onClick={() => setFormData({ ...formData, type: 'virtual' })}
                                className={`p-3 rounded-xl border-2 font-bold text-sm transition-all ${formData.type === 'virtual' ? 'border-purple-500 bg-purple-50 text-purple-700' : 'border-gray-100 text-gray-500 hover:border-gray-200'}`}
                            >
                                Virtual
                            </button>
                        </div>
                    </div>

                    <div className="grid grid-cols-2 gap-4">
                        <FloatingLabelInput
                            type="date"
                            label="Fecha"
                            value={formData.date}
                            onChange={(e: any) => setFormData({ ...formData, date: e.target.value })}
                            containerClassName="!mb-0"
                        />
                        <div>
                            <label className="block text-sm font-bold text-gray-700 mb-1 ml-1">Hora (60 min)</label>
                            <select
                                className="w-full px-4 py-3 bg-gray-50 border-2 border-gray-100 rounded-xl focus:border-blue-500 focus:ring-4 focus:ring-blue-500/10 outline-none transition-all font-medium text-gray-700"
                                value={formData.time}
                                onChange={e => setFormData({ ...formData, time: e.target.value })}
                            >
                                {TIME_SLOTS.map(slot => (
                                    <option key={slot} value={slot}>{slot}</option>
                                ))}
                            </select>
                        </div>
                    </div>

                    {/* Availability Indicator */}
                    <div className="min-h-[24px]">
                        {checking ? (
                            <p className="text-xs text-gray-500 flex items-center gap-1">
                                <Clock size={12} className="animate-spin" /> Verificando disponibilidad...
                            </p>
                        ) : availabilityMsg ? (
                            <p className={`text-xs font-bold flex items-center gap-1 ${availabilityMsg.type === 'success' ? 'text-green-600' : 'text-red-500'}`}>
                                {availabilityMsg.type === 'success' ? <CheckCircle size={12} /> : <AlertCircle size={12} />}
                                {availabilityMsg.text}
                            </p>
                        ) : null}
                    </div>

                    <FloatingLabelInput
                        label="Motivo de la consulta"
                        value={formData.reason}
                        onChange={(e: any) => setFormData({ ...formData, reason: e.target.value })}
                    />

                    {suggestion && (
                        <div className="mt-2 bg-blue-50 border border-blue-100 rounded-lg p-3 flex items-center justify-between animate-in fade-in slide-in-from-top-2">
                            <div className="flex items-center gap-2 text-sm text-blue-800">
                                <Lightbulb size={16} className="text-blue-600 flex-shrink-0" />
                                <span>
                                    <span className="font-bold">Sugerencia cl+°nica:</span> Control en {suggestion.label}
                                </span>
                            </div>
                            <button
                                onClick={() => setFormData({ ...formData, date: suggestion.date })}
                                className="text-xs font-bold bg-white text-blue-600 border border-blue-200 px-3 py-1.5 rounded-lg hover:bg-blue-50 transition-colors shadow-sm whitespace-nowrap"
                            >
                                Aplicar fecha ({new Date(suggestion.date).toLocaleDateString()})
                            </button>
                        </div>
                    )}

                    <div className="pt-4 flex gap-3">
                        <button
                            onClick={onClose}
                            className="flex-1 px-4 py-3 text-gray-600 font-bold hover:bg-gray-50 rounded-xl transition-colors"
                        >
                            Cancelar
                        </button>
                        <button
                            onClick={handleSubmit}
                            disabled={loading || availabilityMsg?.type === 'error'}
                            className="flex-1 px-4 py-3 bg-blue-600 text-white font-bold rounded-xl hover:bg-blue-700 transition-all shadow-lg shadow-blue-600/20 disabled:opacity-50 disabled:cursor-not-allowed"
                        >
                            {loading ? 'Agendando...' : 'Confirmar Cita'}
                        </button>
                    </div>
                </div>
            </GlassCard>
        </div>
    );
};

