            {/* Messages Area */}
            <div className="flex-1 overflow-y-auto p-4 space-y-4 scrollbar-thin scrollbar-thumb-gray-300 dark:scrollbar-thumb-gray-600">
                {messages.map((msg) => {
                    const isMe = msg.senderId === currentUserId;
                    return (
                        <motion.div
                            key={msg.id}
