                                        {Array.isArray(h.medicalOrders) && h.medicalOrders.length > 0 && (
                                            <ActionButtonSmall
                                                icon={<ClipboardList size={16} />}
                                                onClick={() => onViewOrders?.(h)}
                                                color="emerald"
                                            />
                                        )}
                                        <ActionButtonSmall
                                            icon={<Edit size={16} />}
                                            onClick={() => navigate(`/app/history/${patient.id}`, { state: { history: h } })}
                                            color="amber"
                                        />
                                    </>
                                )}
                                <ActionButtonSmall
                                    icon={<Trash2 size={16} />}
