// ============================================================
// 3. IMAGE COMPRESSION (Reduces Storage costs by 50-80%)
// ============================================================

export interface CompressionOptions {
    maxWidth?: number;
    maxHeight?: number;
    quality?: number; // 0.1 to 1.0
    format?: 'jpeg' | 'webp';
}

const DEFAULT_COMPRESSION: CompressionOptions = {
    maxWidth: 1920,
    maxHeight: 1080,
    quality: 0.8,
    format: 'webp'
};

/**
 * Compress an image file before uploading to Firebase Storage
 * Reduces file size by 50-80% while maintaining good quality
 */
export const compressImage = async (
    file: File,
    options: CompressionOptions = {}
): Promise<File> => {
    const opts = { ...DEFAULT_COMPRESSION, ...options };

    // Skip compression for non-images
    if (!file.type.startsWith('image/')) {
        return file;
    }

    // Skip if already small (< 100KB)
    if (file.size < 100 * 1024) {
        return file;
    }

    return new Promise((resolve, reject) => {
        const img = new Image();
        const canvas = document.createElement('canvas');
        const ctx = canvas.getContext('2d');

        img.onload = () => {
            // Calculate new dimensions maintaining aspect ratio
            let { width, height } = img;
            const maxW = opts.maxWidth!;
            const maxH = opts.maxHeight!;

            if (width > maxW || height > maxH) {
                const ratio = Math.min(maxW / width, maxH / height);
                width = Math.round(width * ratio);
                height = Math.round(height * ratio);
            }

            canvas.width = width;
            canvas.height = height;

            // Draw and compress
            ctx?.drawImage(img, 0, 0, width, height);

            canvas.toBlob(
                (blob) => {
                    if (blob) {
                        // Create new file with compressed data
                        const compressedFile = new File(
                            [blob],
                            file.name.replace(/\.[^.]+$/, `.${opts.format}`),
                            { type: `image/${opts.format}` }
                        );



                        resolve(compressedFile);
                    } else {
                        reject(new Error('Failed to compress image'));
                    }
                },
                `image/${opts.format}`,
                opts.quality
            );
        };

        img.onerror = () => reject(new Error('Failed to load image'));
        img.src = URL.createObjectURL(file);
    });
};

/**
 * Format bytes to human readable string
 */
const formatBytes = (bytes: number): string => {
    if (bytes < 1024) return `${bytes} B`;
    if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
    return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
};

// ============================================================
// 4. BATCH OPERATIONS (Reduces write costs)
// ============================================================

/**
 * Debounce function to batch rapid updates
 */
export const debounce = <T extends (...args: any[]) => any>(
    fn: T,
    delay: number
): ((...args: Parameters<T>) => void) => {
    let timeoutId: ReturnType<typeof setTimeout> | null = null;

    return (...args: Parameters<T>) => {
        if (timeoutId) clearTimeout(timeoutId);
        timeoutId = setTimeout(() => fn(...args), delay);
    };
};

/**
 * Throttle function for rate limiting
 */
export const throttle = <T extends (...args: any[]) => any>(
    fn: T,
    limit: number
): ((...args: Parameters<T>) => void) => {
    let inThrottle = false;

    return (...args: Parameters<T>) => {
        if (!inThrottle) {
            fn(...args);
            inThrottle = true;
            setTimeout(() => (inThrottle = false), limit);
        }
    };
};

// ============================================================
// 5. SMART FETCH WITH STALE-WHILE-REVALIDATE
// ============================================================

/**
 * Fetch data with stale-while-revalidate pattern
 * Returns cached data immediately, then updates in background
 */
export const fetchWithSWR = async <T>(
    key: string,
    fetchFn: () => Promise<T>,
    onUpdate?: (data: T) => void
): Promise<T> => {
    // Try to get from cache first
    const cached = await firestoreCache.getOrFetch(key, async () => null, 0);

    if (cached) {
        // Return stale data immediately
        setTimeout(async () => {
            try {
                // Revalidate in background
                firestoreCache.invalidate(key);
                const fresh = await firestoreCache.getOrFetch(key, fetchFn);
                if (onUpdate && JSON.stringify(fresh) !== JSON.stringify(cached)) {
                    onUpdate(fresh);
                }
            } catch (error) {
                console.warn('SWR revalidation failed:', error);
            }
        }, 0);

        return cached;
    }

    // No cache, fetch fresh
    return firestoreCache.getOrFetch(key, fetchFn);
};

// ============================================================
// 6. LOCAL STORAGE PERSISTENCE (Survives page refresh)
// ============================================================

const STORAGE_PREFIX = 'hc_cache_';

/**
 * Save data to localStorage with expiration
 */
export const persistToStorage = <T>(key: string, data: T, ttlMs: number = 24 * 60 * 60 * 1000): void => {
    try {
        const entry = {
            data,
            expiresAt: Date.now() + ttlMs
        };
        localStorage.setItem(STORAGE_PREFIX + key, JSON.stringify(entry));
    } catch (error) {
        console.warn('Failed to persist to localStorage:', error);
    }
};

/**
 * Get data from localStorage if not expired
 */
export const getFromStorage = <T>(key: string): T | null => {
    try {
        const raw = localStorage.getItem(STORAGE_PREFIX + key);
        if (!raw) return null;

        const entry = JSON.parse(raw);
        if (Date.now() > entry.expiresAt) {
            localStorage.removeItem(STORAGE_PREFIX + key);
            return null;
        }

        return entry.data as T;
    } catch (error) {
        return null;
    }
};

/**
 * Clear all cached data from localStorage
 */
export const clearStorageCache = (): void => {
    const keysToRemove: string[] = [];
    for (let i = 0; i < localStorage.length; i++) {
        const key = localStorage.key(i);
        if (key?.startsWith(STORAGE_PREFIX)) {
            keysToRemove.push(key);
        }
    }
    keysToRemove.forEach(key => localStorage.removeItem(key));
};

/**
 * Error Handler Centralizado
 * 
 * Proporciona manejo de errores consistente con:
 * - Clasificaci+¶n de errores por tipo
 * - Mensajes amigables en espa+¶ol
 * - Logging estructurado
 * - Retry autom+Ìtico para errores de red
 */

// ============================================================
// TIPOS DE ERROR
// ============================================================

export type ErrorType =
    | 'network'      // Sin conexi+¶n, timeout
    | 'auth'         // No autenticado, sesi+¶n expirada
    | 'permission'   // Sin permisos
    | 'validation'   // Datos inv+Ìlidos
    | 'not_found'    // Recurso no encontrado
    | 'firebase'     // Errores espec+°ficos de Firebase
    | 'unknown';     // Errores desconocidos

export interface AppError {
    type: ErrorType;
    code: string;
    message: string;           // Mensaje t+¨cnico
    userMessage: string;       // Mensaje amigable para el usuario
    originalError?: Error;
    retryable: boolean;
}

// ============================================================
// MAPEO DE MENSAJES EN ESPA+ÊOL
// ============================================================

const USER_MESSAGES: Record<ErrorType, string> = {
    network: 'No hay conexi+¶n a internet. Por favor, verifica tu conexi+¶n e intenta de nuevo.',
    auth: 'Tu sesi+¶n ha expirado. Por favor, inicia sesi+¶n nuevamente.',
    permission: 'No tienes permisos para realizar esta acci+¶n.',
    validation: 'Los datos ingresados no son v+Ìlidos. Por favor, revisa e intenta de nuevo.',
    not_found: 'El recurso solicitado no fue encontrado.',
    firebase: 'Ocurri+¶ un error al procesar tu solicitud. Intenta de nuevo.',
    unknown: 'Ocurri+¶ un error inesperado. Por favor, intenta de nuevo m+Ìs tarde.'
};

// Firebase error codes a mensajes espec+°ficos
const FIREBASE_MESSAGES: Record<string, string> = {
    'permission-denied': 'No tienes permisos para acceder a estos datos.',
    'unavailable': 'El servicio no est+Ì disponible. Intenta m+Ìs tarde.',
    'deadline-exceeded': 'La operaci+¶n tard+¶ demasiado. Intenta de nuevo.',
    'resource-exhausted': 'Has realizado muchas solicitudes. Espera un momento.',
    'failed-precondition': 'La operaci+¶n no puede realizarse en este momento.',
    'auth/user-not-found': 'No existe una cuenta con este correo electr+¶nico.',
    'auth/wrong-password': 'La contrase+¶a es incorrecta.',
    'auth/email-already-in-use': 'Este correo electr+¶nico ya est+Ì registrado.',
    'auth/weak-password': 'La contrase+¶a debe tener al menos 6 caracteres.',
    'auth/invalid-email': 'El correo electr+¶nico no es v+Ìlido.',
    'auth/too-many-requests': 'Demasiados intentos fallidos. Intenta m+Ìs tarde.',
    'auth/network-request-failed': 'Error de conexi+¶n. Verifica tu internet.',
};

// ============================================================
// CLASIFICACI+ÙN DE ERRORES
// ============================================================

/**
 * Clasifica un error y retorna informaci+¶n estructurada
 */
export function classifyError(error: unknown): AppError {
    // Si ya es un AppError, retornarlo
    if (isAppError(error)) {
        return error;
    }

    const err = error as any;

    // Error de red (fetch failed, timeout, etc.)
    if (isNetworkError(err)) {
        return {
            type: 'network',
            code: 'NETWORK_ERROR',
            message: err.message || 'Network error',
            userMessage: USER_MESSAGES.network,
            originalError: err,
            retryable: true
        };
    }

    // Errores de Firebase
    if (err?.code) {
        const code = err.code;

        // Auth errors
        if (code.startsWith('auth/')) {
            return {
                type: 'auth',
                code,
                message: err.message,
                userMessage: FIREBASE_MESSAGES[code] || USER_MESSAGES.auth,
                originalError: err,
                retryable: false
            };
        }

        // Permission errors
        if (code === 'permission-denied') {
            return {
                type: 'permission',
                code,
                message: err.message,
                userMessage: FIREBASE_MESSAGES[code] || USER_MESSAGES.permission,
                originalError: err,
                retryable: false
            };
        }

        // Retryable Firebase errors
        if (['unavailable', 'deadline-exceeded'].includes(code)) {
            return {
                type: 'firebase',
                code,
                message: err.message,
                userMessage: FIREBASE_MESSAGES[code] || USER_MESSAGES.firebase,
                originalError: err,
                retryable: true
            };
        }

        // Other Firebase errors
        return {
            type: 'firebase',
            code,
            message: err.message,
            userMessage: FIREBASE_MESSAGES[code] || USER_MESSAGES.firebase,
            originalError: err,
            retryable: false
        };
    }

    // Error gen+¨rico
    return {
        type: 'unknown',
        code: 'UNKNOWN_ERROR',
        message: err?.message || String(error),
        userMessage: USER_MESSAGES.unknown,
        originalError: err instanceof Error ? err : undefined,
        retryable: false
    };
}

// ============================================================
// UTILIDADES
// ============================================================

function isAppError(error: unknown): error is AppError {
    return (
        typeof error === 'object' &&
        error !== null &&
        'type' in error &&
        'code' in error &&
        'userMessage' in error
    );
}

function isNetworkError(error: any): boolean {
    if (!error) return false;

    const message = error.message?.toLowerCase() || '';
    const name = error.name?.toLowerCase() || '';

    return (
        name === 'typeerror' && message.includes('fetch') ||
        message.includes('network') ||
        message.includes('timeout') ||
        message.includes('offline') ||
        message.includes('connection') ||
        error.code === 'ECONNREFUSED' ||
        error.code === 'ENOTFOUND'
    );
}

// ============================================================
// RETRY CON BACKOFF EXPONENCIAL
// ============================================================

interface RetryOptions {
    maxAttempts?: number;
    baseDelay?: number;
    maxDelay?: number;
}

/**
 * Ejecuta una funci+¶n con retry autom+Ìtico para errores de red
 */
export async function withRetry<T>(
    fn: () => Promise<T>,
    options: RetryOptions = {}
): Promise<T> {
    const {
        maxAttempts = 3,
        baseDelay = 1000,
        maxDelay = 10000
    } = options;

    let lastError: AppError | null = null;

    for (let attempt = 1; attempt <= maxAttempts; attempt++) {
        try {
            return await fn();
        } catch (error) {
            lastError = classifyError(error);

            // Solo reintentar si es un error recuperable
            if (!lastError.retryable || attempt === maxAttempts) {
                throw lastError;
            }

            // Calcular delay con exponential backoff
            const delay = Math.min(baseDelay * Math.pow(2, attempt - 1), maxDelay);


            await sleep(delay);
        }
    }

    throw lastError;
}

function sleep(ms: number): Promise<void> {
    return new Promise(resolve => setTimeout(resolve, ms));
}

// ============================================================
// LOGGING
// ============================================================

/**
 * Log estructurado de errores
 */
export function logError(error: AppError, context?: string): void {
    const logData = {
        timestamp: new Date().toISOString(),
        type: error.type,
        code: error.code,
        message: error.message,
        context,
        retryable: error.retryable
    };

    console.error('=Éˆ¶ Error:', logData);

    // En producci+¶n, aqu+° se enviar+°a a un servicio de logging
    // como Sentry, LogRocket, etc.
}

/**
 * Muestra un error al usuario (puede integrarse con toast/alert)
 */
export function showUserError(error: AppError): void {
    // Por defecto usa console, pero puede integrarse con un sistema de notificaciones
    console.warn(`G‹·n+≈ ${error.userMessage}`);
}

