export interface OfflineAction {
    id: string;
    type: string;
    data: any;
    timestamp: number;
    retryCount: number;
}

const STORAGE_KEY = 'offline_queue_v1';
// Privileged roles that can use offline mode (no hardcoded emails)
const ALLOWED_ROLES = ['doctor', 'admin', 'assistant'];

class OfflineQueueManager {

    /**
     * Verifica si el usuario actual tiene permisos para usar el modo offline
     * @param userRole - Role del usuario desde AuthContext (no email)
     */
    canUseOfflineMode(userRole: string | null): boolean {
        if (!userRole) return false;
        return ALLOWED_ROLES.includes(userRole);
    }

    /**
     * Guarda una acci+¶n en la cola offline
     */
    enqueueAction(actionType: string, data: any, userEmail: string | null) {
        if (!this.canUseOfflineMode(userEmail)) {
            console.warn('Offline mode not allowed for this user');
            return;
        }

        const queue = this.getQueue();
        const newAction: OfflineAction = {
            id: crypto.randomUUID(),
            type: actionType,
            data,
            timestamp: Date.now(),
            retryCount: 0
        };

        queue.push(newAction);
        localStorage.setItem(STORAGE_KEY, JSON.stringify(queue));

        // Dispatch event to update UI immediately
        window.dispatchEvent(new Event('offline-queue-changed'));
    }

    /**
     * Obtiene la cola actual
     */
    getQueue(): OfflineAction[] {
        try {
            const stored = localStorage.getItem(STORAGE_KEY);
            return stored ? JSON.parse(stored) : [];
        } catch (e) {
            console.error('Error reading offline queue', e);
            return [];
        }
    }

    /**
     * Elimina una acci+¶n de la cola (al completarse)
     */
    removeAction(id: string) {
        const queue = this.getQueue();
        const filtered = queue.filter(item => item.id !== id);
        localStorage.setItem(STORAGE_KEY, JSON.stringify(filtered));
        window.dispatchEvent(new Event('offline-queue-changed'));
    }

    /**
     * Limpia toda la cola
     */
    clearQueue() {
        localStorage.removeItem(STORAGE_KEY);
        window.dispatchEvent(new Event('offline-queue-changed'));
    }
}

export const offlineQueue = new OfflineQueueManager();

/**
 * Payment Service for Firebase Cloud Functions
 * Uses httpsCallable to invoke payment processing functions
 */

import { getFunctions, httpsCallable, HttpsCallableResult } from 'firebase/functions';
import { getApp } from 'firebase/app';

// ============================================================
// TYPES
// ============================================================

export type PaymentGateway = 'stripe' | 'tilopay' | 'powertranz';

export interface PaymentRequest {
    amount: number;
    currency?: string;
    gateway: PaymentGateway;
    appointmentId?: string;
    patientId?: string;
    description?: string;
    customerEmail?: string;
    customerName?: string;
}

export interface PaymentResponse {
    success: boolean;
    gateway: string;
    transactionId?: string;
    clientSecret?: string;
    redirectUrl?: string;
    message?: string;
}

export interface InitiatePaymentRequest {
    appointmentId: string;
    patientId: string;
    amount: number;
    gateway: PaymentGateway;
}

// ============================================================
// CLOUD FUNCTION CALLS
// ============================================================

/**
 * Get Firebase Functions instance
 */
function getFunctionsInstance() {
    const app = getApp();
    return getFunctions(app, 'us-central1');
}

/**
 * Create a payment intent using the specified gateway
 * This is the main function to initiate a payment
 * 
 * @example
 * const result = await createPaymentIntent({
 *   amount: 1200,
 *   currency: 'NIO',
 *   gateway: 'tilopay',
 *   appointmentId: 'abc123',
 *   patientId: 'patient123',
 *   customerEmail: 'patient@email.com',
 *   customerName: 'Juan Perez'
 * });
 * 
 * if (result.redirectUrl) {
 *   window.location.href = result.redirectUrl;
 * }
 */
export async function createPaymentIntent(request: PaymentRequest): Promise<PaymentResponse> {
    const functions = getFunctionsInstance();
    const createPaymentIntentFn = httpsCallable<PaymentRequest, PaymentResponse>(
        functions,
        'createPaymentIntent'
    );

    try {
        const result: HttpsCallableResult<PaymentResponse> = await createPaymentIntentFn(request);
        return result.data;
    } catch (error: any) {
        console.error('createPaymentIntent error:', error);
        throw new Error(error.message || 'Error al crear intenci+¶n de pago');
    }
}

/**
 * Legacy function for backwards compatibility
 * Uses the older initiatePayment Cloud Function
 */
export async function initiatePayment(request: InitiatePaymentRequest): Promise<PaymentResponse> {
    const functions = getFunctionsInstance();
    const initiatePaymentFn = httpsCallable<InitiatePaymentRequest, PaymentResponse>(
        functions,
        'initiatePayment'
    );

    try {
        const result: HttpsCallableResult<PaymentResponse> = await initiatePaymentFn(request);
        return result.data;
    } catch (error: any) {
        console.error('initiatePayment error:', error);
        throw new Error(error.message || 'Error al iniciar pago');
    }
}

// ============================================================
// STRIPE HELPERS
// ============================================================

/**
 * Create a Stripe payment intent and get client secret
 * Use this with @stripe/stripe-js on the frontend
 * 
 * @example
 * const { clientSecret } = await createStripePayment(1200);
 * const stripe = await loadStripe('pk_live_xxx');
 * await stripe.confirmCardPayment(clientSecret, { ... });
 */
export async function createStripePayment(
    amount: number,
    appointmentId?: string,
    patientId?: string
): Promise<{ clientSecret: string; transactionId: string }> {
    const response = await createPaymentIntent({
        amount,
        currency: 'USD',
        gateway: 'stripe',
        appointmentId,
        patientId,
    });

    if (!response.clientSecret) {
        throw new Error('No se recibi+¶ clientSecret de Stripe');
    }

    return {
        clientSecret: response.clientSecret,
        transactionId: response.transactionId || '',
    };
}

// ============================================================
// TILOPAY HELPERS (Nicaragua/Central America)
// ============================================================

/**
 * Create a TiloPay payment and get redirect URL
 * User will be redirected to TiloPay checkout page
 * 
 * @example
 * const { redirectUrl } = await createTiloPayPayment({
 *   amount: 1200,
 *   appointmentId: 'apt123',
 *   customerEmail: 'patient@email.com',
 *   customerName: 'Juan Perez'
 * });
 * window.location.href = redirectUrl;
 */
export async function createTiloPayPayment(params: {
    amount: number;
    appointmentId?: string;
    patientId?: string;
    customerEmail?: string;
    customerName?: string;
}): Promise<{ redirectUrl: string; transactionId: string }> {
    const response = await createPaymentIntent({
        amount: params.amount,
        currency: 'NIO', // Nicaraguan C+¶rdoba
        gateway: 'tilopay',
        appointmentId: params.appointmentId,
        patientId: params.patientId,
        customerEmail: params.customerEmail,
        customerName: params.customerName,
    });

    if (!response.redirectUrl) {
        throw new Error('No se recibi+¶ URL de redirecci+¶n de TiloPay');
    }

    return {
        redirectUrl: response.redirectUrl,
        transactionId: response.transactionId || '',
    };
}

