/**
 * Format amount for display
 */
export function formatCurrency(amount: number, currency: string = 'NIO'): string {
    const formatter = new Intl.NumberFormat('es-NI', {
        style: 'currency',
        currency: currency,
    });
    return formatter.format(amount);
}

