 */
export const generateReceiptPDF = (
    patient: Patient,
    consultDate: string,
    consultationType: string,
    cost: number,
    doctorName: string = 'Dr. M+¨dico'
): void => {
    const doc = new jsPDF();
    const pageWidth = doc.internal.pageSize.getWidth();
    let yPos = 20;

    // Header
    doc.setFillColor(8, 60, 121);
    doc.rect(0, 0, pageWidth, 40, 'F');

    doc.setTextColor(255, 255, 255);
    doc.setFontSize(20);
    doc.setFont('helvetica', 'bold');
    doc.text('Recibo de Consulta', pageWidth / 2, 25, { align: 'center' });

    yPos = 55;

    // Receipt number
    doc.setTextColor(8, 60, 121);
    doc.setFontSize(12);
    doc.setFont('helvetica', 'bold');
    doc.text(`Recibo No: ${Date.now().toString().slice(-8)}`, 15, yPos);
    doc.text(`Fecha: ${new Date().toLocaleDateString('es-NI')}`, pageWidth - 70, yPos);
    yPos += 20;

    // Patient details
    doc.setTextColor(0, 0, 0);
    doc.setFontSize(11);

    const receiptData = [
        ['Paciente:', `${patient.firstName} ${patient.lastName}`],
        ['Fecha de Consulta:', consultDate],
        ['Tipo de Consulta:', consultationType],
        ['', ''],
        ['TOTAL:', `$${cost.toFixed(2)}`]
    ];

    doc.autoTable({
        startY: yPos,
        head: [],
        body: receiptData,
        theme: 'plain',
        styles: { fontSize: 12, cellPadding: 5 },
        columnStyles: {
            0: { fontStyle: 'bold', cellWidth: 60 },
            1: { cellWidth: 120 }
        },
        margin: { left: 15 },
        didParseCell: function (data: any) {
            if (data.row.index === 4) {
                data.cell.styles.fontSize = 16;
                data.cell.styles.fontStyle = 'bold';
                data.cell.styles.textColor = [8, 60, 121];
            }
        }
    });

    yPos = doc.lastAutoTable.finalY + 30;

    // Thank you message
    doc.setFontSize(10);
    doc.setTextColor(100, 100, 100);
    doc.text('Gracias por su confianza.', pageWidth / 2, yPos, { align: 'center' });

    // Footer
    doc.setFontSize(8);
    doc.setTextColor(128, 128, 128);
    doc.text(
        doctorName,
        pageWidth / 2,
        doc.internal.pageSize.getHeight() - 15,
        { align: 'center' }
    );

    // Save
    const fileName = `Recibo_${patient.lastName}_${consultDate}.pdf`;
    doc.save(fileName);
};

import React, { useEffect } from 'react';
import { LoginScreen } from './LoginScreen';
import { useNavigate, useSearchParams } from 'react-router-dom';
import { useAuth } from '../../context/AuthContext';

export const AuthPage = () => {
    const navigate = useNavigate();
    const [searchParams] = useSearchParams();
    const { currentUser } = useAuth();

    useEffect(() => {
        if (currentUser) {
            // Check roles or user data in Firestore later
            // For now, redirect to main app
            navigate('/app');
        }
    }, [currentUser, navigate]);

    const handlePatientAccess = () => {
        navigate('/app/patient/login');
    };

    const roleParam = searchParams.get('role');
    // Map URL param to LoginScreen props (using 'any' to bypass strict 'clinic'|'doctor' type if needed or update type)
    const initialRole = (roleParam === 'doctor' || roleParam === 'assistant') ? roleParam : undefined;

    return (
        <LoginScreen
            onLogin={() => { }}
            onPatientAccess={handlePatientAccess}
            initialRole={initialRole as any}
        />
    );
};

import React, { useState } from 'react';
