        try {
            await signIn(email, password);
            // TODO: Save selectedSpecialty.id to user profile or context
            navigate('/app/home');
        } catch (err: any) {
            setLoginError(
                err?.code === 'auth/invalid-credential'
                    ? 'Credenciales inv+Ìlidas. Verifica tu email y contrase+¶a.'
                    : err?.code === 'auth/too-many-requests'
                        ? 'Demasiados intentos. Intenta m+Ìs tarde.'
                        : 'Error al iniciar sesi+¶n. Intenta de nuevo.'
            );
        } finally {
            setIsLoading(false);
