                    backgroundSize: '40px 40px',
                }} />
            </div>

            <motion.div
                className="w-full max-w-5xl relative z-10"
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ duration: 0.5 }}
            >
                {/* Header */}
