        motives: {},
        otherMotive: '',
        evolutionTime: '',
        historyOfPresentIllness: '',
        physicalExam: {
            fc: '', fr: '', temp: '', pa: '', pam: '', sat02: '', weight: '', height: '', imc: '',
            systems: C.SYSTEMS_LIST.reduce((acc, sys) => ({ ...acc, [sys]: { normal: true, abnormal: false, description: '' } }), {})
        },
        labs: {
            performed: { yes: false, no: true },
