    const handleDiagnosisChange = (index: number, value: string) => {
        setC(prev => {
            const newDiagnoses = [...prev.diagnoses];
            newDiagnoses[index] = value;
            return { ...prev, diagnoses: newDiagnoses };
        });
    };

