                {!history ? (
                    <div className="bg-white p-8 rounded-2xl shadow-sm text-center">
                        <AlertTriangle className="mx-auto text-yellow-500 mb-4" size={48} />
                        <h2 className="text-xl font-bold text-gray-800">No se encontr+¶ historia cl+°nica</h2>
                        <p className="text-gray-500 mt-2">Este paciente parece tener datos migrados pero no se encontr+¶ la colecci+¶n de historia cl+°nica correspondiente.</p>
