    { key: 'infectious', label: 'Infecciosas', path: h => h.infectious },
    { key: 'psychiatric', label: 'Psiqui+Ìtricas', path: h => h.psychiatric },
  ];

  const antecedentes: Record<string, { yes: number; total: number }> = {};
  histories.forEach(h => {
    antecedentFields.forEach(({ key, path }) => {
      const field = path(h);
      if (field) {
