// --- ESTILOS GLOBALES ---
const inputClass = "w-full px-4 py-3 rounded-xl border-2 border-black font-medium text-[#084286] placeholder-gray-400 focus:border-[#084286] focus:ring-2 focus:ring-[#084286]/20 outline-none transition-all";
